function etUserKey(ident) {
  if (!ident || typeof ident !== "object") return null;
  var first = String(ident.firstName || "").trim().toLowerCase().replace(/[^a-z0-9]/g, "");
  if (!first) return null;
  var firstInitial = first.charAt(0);
  if (!firstInitial) return null;
  var full = String(ident.name || "").trim();
  var parts = full.split(/\s+/).filter(Boolean);
  var lastInitial = "";
  if (parts.length >= 2) {
    var last = parts[parts.length - 1].toLowerCase().replace(/[^a-z0-9]/g, "");
    if (last) lastInitial = last.charAt(0);
  }
