        var em = ex[model] || { promptTokens: 0, candidatesTokens: 0, calls: 0 };
        var dm = dx[model] || {};
        em.promptTokens     = Math.max(Number(em.promptTokens)     || 0, Number(dm.promptTokens)     || 0);
        em.candidatesTokens = Math.max(Number(em.candidatesTokens) || 0, Number(dm.candidatesTokens) || 0);
        em.calls            = Math.max(Number(em.calls)            || 0, Number(dm.calls)            || 0);
        ex[model] = em;
