  // bundler puts each top-level fn in its own eval scope, so this
  // function can't see sibling etEstimateCost. init.js calls
  // etEstimateCost on each merged day after this returns (it has
  // both helpers in scope via efns).
  var sortedDays = Object.keys(byDate).sort().map(function (k) {
    return byDate[k];
  });
