    // Prefer local's userName/userKey since it reflects the running
    // session's identity; remote is just last-written value.
    userName: (local.userName || remote.userName || ""),
    userKey: (local.userKey || remote.userKey || ""),
    generatedAt: (local.generatedAt || new Date().toISOString()),
