// Estimate USD cost from a per-model tokens map: { "<model>": {
// promptTokens, candidatesTokens, calls } }. Returns { totalUSD,
// byModel: { "<model>": usd } }. Caller decides display precision.
// 2026-05-18 v26: price table INLINED — bundler isolates each top-
// level fn into its own eval scope, so this function can't call
// sibling etPriceTable. Keep the two tables identical; etPriceTable
// stays exported for external callers that want just the rates.

engine.etEstimateCost:
function etEstimateCost(tokensMap) {
  var prices = {
    "gemini-3.1-flash-lite-preview":     { in: 0.04, out: 0.20 },
    "gemini-3.1-flash":                  { in: 0.075, out: 0.30 },
    "gemini-2.5-flash":                  { in: 0.075, out: 0.30 },
    "gemini-2.5-flash-lite-preview":     { in: 0.04, out: 0.20 },
    "gemini-2.5-pro":                    { in: 1.25, out: 5.00 },
    "gemini-1.5-pro":                    { in: 1.25, out: 5.00 },
    "gemini-1.5-flash":                  { in: 0.075, out: 0.30 },
    "_default":                          { in: 0.075, out: 0.30 },
  };
  var out = { totalUSD: 0, byModel: {} };
  if (!tokensMap || typeof tokensMap !== "object") return out;
  Object.keys(tokensMap).forEach(function (model) {
    var t = tokensMap[model] || {};
    var price = prices[model] || prices._default;
    var inTok  = Number(t.promptTokens) || 0;
    var outTok = Number(t.candidatesTokens) || 0;
    var usd = (inTok * price.in + outTok * price.out) / 1000000;
    out.byModel[model] = usd;
    out.totalUSD += usd;
  });
  return out;
}

// Build the digest payload pushed to GitHub. Input: array of telemetry
// rows for one user (already pruned). Output: { userName, userKey,
// generatedAt, days } where days is ordered ascending by date.
// 2026-05-17: each day now also carries `tokens` (per-model breakdown)
// and `estCostUSD` (computed from etPriceTable above).

engine.etBuildDigest:
function etBuildDigest(rows, userName, userKey) {
  var sorted = (Array.isArray(rows) ? rows : []).slice().sort(function (a, b) {
    return String(a.date || "").localeCompare(String(b.date || ""));
  });
