    userName: String(userName || ""),
    userKey: String(userKey || ""),
    generatedAt: new Date().toISOString(),
    days: sorted.map(function (r) {
      var tokensMap = r.tokens || {};
      // 2026-05-18 v25: estCostUSD computed in init.js after this
      // returns — bundler isolates each top-level fn so sibling
      // etEstimateCost isn't visible from here. Stub the field
      // (init.js will overwrite via the engine helper).
      return {
        date: r.date || "",
        toolsUsed: r.toolsUsed || {},
        sessions: Number(r.sessions || 0),
        firstActiveAt: Number(r.firstActiveAt || 0),
        lastActiveAt: Number(r.lastActiveAt || 0),
        tokens: tokensMap,
        // 2026-05-18 v61: per-tool token attribution. Shape:
        // { toolName: { model: { promptTokens, candidatesTokens, calls } } }
        // Lets the viewer compute per-tool cost per user per day.
        tokensByTool: r.tokensByTool || {},
        estCostUSD: 0,
      };
    }),
  };
}

