  // IDB was being re-fired on each boot via _reevaluateHydratedMetrics
  // → _fireTrophy → bus emit → _onStatsRecorded → _recordToolLaunch.
  // Symptom: user resets local, reloads, sees review_redlines:1 (or
  // any other previously-clicked tool) with no clicks. The bug
  // inflated every tool the user had EVER opened, on EVERY reload.
  // This IGNORED_TOOLS list had grown reactively (risk, legal_risks,
  // usage_risks, etc.) to mask the symptom tool-by-tool. With the
  // root fix in eli_stats v56, those entries are no longer needed.
  //
  // KEPT entries (intentional exclusions, not bug masks):
  //   - trophy_gallery: sidebar chip on every page; clicks shouldn't
  //     track as "tool launches."
  //   - admin_* tools: diagnostic surface; counting their own opens
  //     pollutes the data they're built to read.
  var IGNORED_TOOLS = {
    trophy_gallery: true, trophyGallery: true,
    admin_storage_inspector: true, storage_inspector: true,
    admin_telemetry_inspector: true, telemetry_inspector: true,
    admin_usage_viewer: true, usage_viewer: true,
    admin_template_studio: true, template_studio: true,
  };

  // ─── Capture: bucket one tool launch ───────────────────────────────
  function _recordToolLaunch(toolName) {
    if (!toolName) return Promise.resolve(false);
    if (IGNORED_TOOLS[toolName]) return Promise.resolve(false);
    var info = etTodayInfo();
    // 2026-05-17 v20: weekend recording RESTORED. Was skipped earlier
    // to capture only weekday work patterns, but weekend manual pushes
    // were returning 0 days and reading as a failure. Now records
    // every day; consumers that care about weekday-only can filter
    // downstream via the row's date / isWeekend flag.
    var ident = _currentIdentity();
    var userKey = etUserKey(ident);
    if (!userKey) return Promise.resolve(false); // anonymous → skip
    // 2026-05-17 v21: write INITIALS only (e.g. "AN" for Andrew
    // Nemiroff), never the full first name.
    var initials = etUserInitials(ident);
    var rowId = _rowKey(userKey, info.date);
    var now = Date.now();
    return _loadRow(userKey, info.date).then(function (existing) {
      var row = existing || {
        key: rowId,  // 2026-05-18 v25: config-store keyPath is "key", not "id".
        userKey: userKey,
        userName: initials,
        date: info.date,
        toolsUsed: {},
        sessions: 0,
        firstActiveAt: now,
        lastActiveAt: now,
      };
      // Upgrade legacy {id:...} rows in case any persisted (defensive).
      if (!row.key && row.id) row.key = row.id;
      // Refresh userName (overwrite — was previously only-if-empty;
      // now always refresh so old full-name rows upgrade to initials).
      if (initials) row.userName = initials;
      row.toolsUsed = row.toolsUsed || {};
      // 2026-05-18 v33: scrub any legacy IGNORED_TOOLS counts that
      // were recorded BEFORE the ignore-list shipped. Cheap O(1)
      // check per launch; persists the clean state on next write.
      Object.keys(IGNORED_TOOLS).forEach(function (k) {
        if (row.toolsUsed && row.toolsUsed.hasOwnProperty(k)) {
          delete row.toolsUsed[k];
        }
      });
      row.toolsUsed[toolName] = (Number(row.toolsUsed[toolName]) || 0) + 1;
      row.lastActiveAt = now;
      if (!row.firstActiveAt) row.firstActiveAt = now;
      // Debounce session counter: one per boot per date.
      if (_sessionMarkedForDate !== info.date) {
        row.sessions = (Number(row.sessions) || 0) + 1;
        _sessionMarkedForDate = info.date;
      }
      return _saveRow(row).then(function () {
        // Fire-and-forget prune; failures are non-fatal.
        _pruneOld(userKey, info.date).catch(function () {});
        return true;
      });
    });
  }

  // ─── Bus subscription ──────────────────────────────────────────────
  // 2026-05-18 v61: track the most-recently-launched tool. Every
  // subsequent `ai:tokens_used` event gets attributed to this tool so
  // we can show per-tool cost breakdowns in the usage viewer. The
  // active-tool model is: last appOpened* stat wins, until the next
  // appOpened* fires. Background async AI work that completes after
  // the user navigates away still attributes to the launching tool,
  // which is what you want for "what's this tool costing me."
  var _activeToolName = null;
  function _onStatsRecorded(payload) {
    if (!payload || !payload.name) return;
    var tool = etDeriveToolName(payload.name);
    if (!tool) return;
    if (IGNORED_TOOLS[tool]) return; // ignored tools shouldn't become active
    _activeToolName = tool;
    _recordToolLaunch(tool).catch(function (e) {
      eli.log.event("telemetry", "record_failed", { msg: e && e.message });
    });
  }

  // 2026-05-18 v41: dedicated session-start handler. Sessions were
  // previously incremented as a side-effect of _recordToolLaunch (gated
  // behind etDeriveToolName returning a tool), so boots where the user
  // never launched a recognized tool — or where the first stats event
  // was a kernel-level event without a tool name — stayed at 0 forever.
  // _recordSessionStart fires once per boot per date, unconditionally,
  // right after telemetry subscribes. Same MAX-merge semantics keep
  // multi-machine pushes coherent.
  function _recordSessionStart() {
    var info = etTodayInfo();
    var ident = _currentIdentity();
    var userKey = etUserKey(ident);
    if (!userKey) return Promise.resolve(false);
    if (_sessionMarkedForDate === info.date) return Promise.resolve(false);
    var initials = etUserInitials(ident);
    var rowId = _rowKey(userKey, info.date);
    var now = Date.now();
    return _loadRow(userKey, info.date).then(function (existing) {
      var row = existing || {
        key: rowId, userKey: userKey, userName: initials, date: info.date,
        toolsUsed: {}, sessions: 0, firstActiveAt: now, lastActiveAt: now,
      };
      if (!row.key && row.id) row.key = row.id;
      if (initials) row.userName = initials;
      row.sessions = (Number(row.sessions) || 0) + 1;
      row.lastActiveAt = now;
      if (!row.firstActiveAt) row.firstActiveAt = now;
      _sessionMarkedForDate = info.date;
      return _saveRow(row);
    });
  }

  // 2026-05-17: subscribe to AI token-usage events emitted by the kernel
  // (eli.ai._attempt). Accumulates per-model promptTokens + candidatesTokens
  // + call counts onto the same daily row as tool launches. Cost is
  // computed at digest-build time via etEstimateCost (engine helper) so
  // we never store stale dollar amounts.
  function _recordTokensUsed(payload) {
    if (!payload || !payload.model) return Promise.resolve(false);
    var info = etTodayInfo();
    // 2026-05-17 v20: weekend recording RESTORED (matches the same
    // change in _recordToolLaunch above).
    var ident = _currentIdentity();
    var userKey = etUserKey(ident);
    if (!userKey) return Promise.resolve(false);
    var initials = etUserInitials(ident);
    var rowId = _rowKey(userKey, info.date);
    var now = Date.now();
    var model = String(payload.model);
    var inTok  = Number(payload.promptTokens) || 0;
    var outTok = Number(payload.candidatesTokens) || 0;
    return _loadRow(userKey, info.date).then(function (existing) {
      var row = existing || {
        key: rowId, userKey: userKey, userName: initials, date: info.date,
        toolsUsed: {}, sessions: 0,
        firstActiveAt: now, lastActiveAt: now,
      };
      if (!row.key && row.id) row.key = row.id;
      if (initials) row.userName = initials;
      // 2026-05-18 v33: same scrub as _recordToolLaunch.
      if (row.toolsUsed) {
        Object.keys(IGNORED_TOOLS).forEach(function (k) {
          if (row.toolsUsed.hasOwnProperty(k)) delete row.toolsUsed[k];
        });
      }
      row.tokens = row.tokens || {};
      var bucket = row.tokens[model] || { promptTokens: 0, candidatesTokens: 0, calls: 0 };
      bucket.promptTokens     += inTok;
      bucket.candidatesTokens += outTok;
      bucket.calls            += 1;
      row.tokens[model] = bucket;
      // 2026-05-18 v61: per-tool token attribution. _activeToolName
      // is set by _onStatsRecorded to the most-recent appOpened*
      // tool — AI work that fires inside the user's session lands
      // here. Falls back to "_unknown" when no tool has been
      // launched yet this session (rare; usually the dashboard tile
      // click sets it before any AI fires). Shape: tokensByTool =
      // { toolName: { model: { promptTokens, candidatesTokens, calls } } }
      var toolForTokens = (payload && payload.toolId) || _activeToolName || "_unknown";
      row.tokensByTool = row.tokensByTool || {};
      var toolBucket = row.tokensByTool[toolForTokens] || {};
      var modelBucket = toolBucket[model] || { promptTokens: 0, candidatesTokens: 0, calls: 0 };
      modelBucket.promptTokens     += inTok;
      modelBucket.candidatesTokens += outTok;
      modelBucket.calls            += 1;
      toolBucket[model] = modelBucket;
      row.tokensByTool[toolForTokens] = toolBucket;
      row.lastActiveAt = now;
      if (!row.firstActiveAt) row.firstActiveAt = now;
      return _saveRow(row).then(function () { return true; });
    });
  }
  function _onTokensUsed(payload) {
    _recordTokensUsed(payload).catch(function (e) {
      eli.log.event("telemetry", "tokens_record_failed", { msg: e && e.message });
    });
  }

  // ─── GitHub push ───────────────────────────────────────────────────
  function _strToB64(s) {
    var bytes = new TextEncoder().encode(s);
    var bin = "";
    for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
    return btoa(bin);
  }

  function _getPat() {
    // PAT is stored plaintext in localStorage as `eli_user_github_pat`
    // (set by importCredentialsBundle). Same key admin_library_publisher
    // reads. No decryption needed.
    try { return String(eli.compat.lsGet("eli_user_github_pat") || "").trim(); }
    catch (e) { return ""; }
  }

  // GET → check existing file, fetch SHA + decoded content. Returns
  // { sha, digest } or null if 404. digest is the parsed JSON object
  // (so the push step can MERGE remote days into the local digest —
  // critical when the user has ELI on two computers pushing to the
  // same usage/<userKey>.json file).
  function _githubGetSha(pat, userKey) {
    var filePath = "usage/" + encodeURIComponent(userKey) + ".json";
    var url = "https://api.github.com/repos/" + GITHUB_OWNER + "/" + GITHUB_REPO +
      "/contents/" + filePath + "?t=" + Date.now();
    return fetch(url, {
      cache: "no-store",
      headers: {
        "Authorization": "Bearer " + pat,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
      },
    }).then(function (r) {
      if (r.status === 404) return null;
      if (!r.ok) throw new Error("GET sha failed: HTTP " + r.status);
      return r.json().then(function (j) {
        var sha = j && j.sha;
        var digest = null;
        try {
          if (j && j.content) {
            var b64 = String(j.content).replace(/\s/g, "");
            var bytes = Uint8Array.from(atob(b64), function (c) { return c.charCodeAt(0); });
            var str = new TextDecoder().decode(bytes);
            digest = JSON.parse(str);
          }
        } catch (_) { digest = null; }
        return { sha: sha, digest: digest };
      });
    });
  }

  // PUT digest to usage/<userkey>.json. Creates on first call, updates after.
  function _githubPut(pat, userKey, digest, existingSha) {
    var filePath = "usage/" + encodeURIComponent(userKey) + ".json";
    var url = "https://api.github.com/repos/" + GITHUB_OWNER + "/" + GITHUB_REPO +
      "/contents/" + filePath;
    var content = JSON.stringify(digest, null, 2);
    var body = {
      message: "Usage update " + new Date().toISOString(),
      content: _strToB64(content),
    };
    if (existingSha) body.sha = existingSha;
    return fetch(url, {
      method: "PUT",
      headers: {
        "Authorization": "Bearer " + pat,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    }).then(function (r) {
      if (!r.ok) {
        return r.text().then(function (t) {
          // 2026-05-23c: bumped 200 → 2000. GitHub Push Protection's 409
          // response includes secret_type + placeholder_id past the 200
          // mark, and that's exactly the info admin needs to diagnose
          // which value triggered the scanner. Still bounded so a runaway
          // server response doesn't blow up the log.
          throw new Error("PUT failed: HTTP " + r.status + " · " + String(t).slice(0, 2000));
        });
      }
      return r.json().then(function () { return true; });
    });
  }

  // Build digest from IDB, push to GitHub. Throttled by lastPush unless force=true.
  // Resolves with { ok, skipped?, reason?, days? } — never throws.
  function _push(opts) {
    opts = opts || {};
    var force = !!opts.force;
    var ident = _currentIdentity();
    var userKey = etUserKey(ident);
    if (!userKey) {
      return Promise.resolve({ ok: false, skipped: true, reason: "no_user_key" });
    }
    var pat = _getPat();
    if (!pat) {
      return Promise.resolve({ ok: false, skipped: true, reason: "no_pat" });
    }
    if (!force) {
      var lastStr = eli.compat.lsGet(LAST_PUSH_KEY);
      var lastNum = lastStr ? Number(lastStr) : 0;
      if (lastNum && (Date.now() - lastNum) < PUSH_THROTTLE_MS) {
        return Promise.resolve({ ok: false, skipped: true, reason: "throttled" });
      }
    }
    return _allUserRows(userKey).then(function (rows) {
      // 2026-05-17 v23: when there are zero rows, run a synthetic
      // _recordToolLaunch("force_push_self_test") to prove whether
      // the write path itself is working. If the self-test row lands,
      // we know IDB writes work — the issue is that real launches
      // aren't reaching _recordToolLaunch (most likely: consent
      // opted_out → bus subscription never happened). The self-test
      // row is captured in the diagnostic so the user sees it.
      var didSelfTest = false;
      var selfTestOk = null;
      var didSelfTestPromise = Promise.resolve(rows);
      if ((rows || []).length === 0) {
        didSelfTest = true;
        didSelfTestPromise = _recordToolLaunch("force_push_self_test")
          .then(function (ok) { selfTestOk = !!ok; })
          .catch(function () { selfTestOk = false; })
          .then(function () { return _allUserRows(userKey); });
      }
      return didSelfTestPromise.then(function (rowsAfterSelfTest) {
        var digest = etBuildDigest(rowsAfterSelfTest, etUserInitials(ident), userKey);
        var isWeekendToday = false;
        try { isWeekendToday = !!(etTodayInfo && etTodayInfo().isWeekend); } catch (_) {}
        var consentState = _readConsent();
        return eli.storage.getAll(STORE_CONFIG).then(function (allConfig) {
          var allTelemetryRows = (allConfig || []).filter(function (r) {
            return r && typeof r.key === "string" && r.key.indexOf(ROW_PREFIX) === 0;
          });
          var otherUserKeys = {};
          allTelemetryRows.forEach(function (r) {
            var trimmed = r.key.slice(ROW_PREFIX.length);
            var lastUnd = trimmed.lastIndexOf("_");
            if (lastUnd > 0) {
              var k = trimmed.slice(0, lastUnd);
              if (k !== userKey) otherUserKeys[k] = (otherUserKeys[k] || 0) + 1;
            }
          });
          return _githubGetSha(pat, userKey).then(function (info) {
            var sha = info && info.sha;
            // 2026-05-18 v25: MERGE the remote digest with the local
            // one before PUT. Handles the multi-computer case where
            // ELI runs on two machines under the same userKey —
            // without merging, each push overwrites the other.
            var remoteDigest = info && info.digest;
            var mergedDigest = (typeof etMergeDigests === "function")
              ? etMergeDigests(remoteDigest, digest)
              : digest;
            // 2026-05-18 v33: defensive scrub of IGNORED_TOOLS at
            // digest-build time. Catches: (a) legacy IDB rows that
            // had counts before the ignore-list shipped, (b) remote
            // digests pushed by a stale client, (c) anything else
            // that snuck through.
            (mergedDigest.days || []).forEach(function (d) {
              if (d && d.toolsUsed) {
                Object.keys(IGNORED_TOOLS).forEach(function (k) {
                  if (d.toolsUsed.hasOwnProperty(k)) delete d.toolsUsed[k];
                });
              }
            });
            _stampCosts(mergedDigest);
            // 2026-05-23: fleet metadata — userId, settings, tools list,
            // kernel version. Lets the admin fleet dashboard (Phase 1b)
            // join telemetry with the local identity lookup. All anonymous
            // on the wire (UUID + initials only, no email or name).
            try {
              var fleetMeta = {};
              if (window.eli && window.eli.settings && typeof window.eli.settings.get === "function") {
                fleetMeta.userId = window.eli.settings.get("user_id") || null;
              }
              fleetMeta.initials = etUserInitials(ident) || null;
              fleetMeta.kernelVersion = (window.eli && window.eli.kernelVersion) || null;
              // installedAt — persisted in localStorage on first run.
              try {
                var installedAt = eli.compat.lsGet("_telemetry_installed_at");
                if (!installedAt) {
                  installedAt = new Date().toISOString();
                  eli.compat.lsSet("_telemetry_installed_at", installedAt);
                }
                fleetMeta.installedAt = installedAt;
              } catch (_e) {}
              fleetMeta.lastSeenAt = new Date().toISOString();
              // Settings dump — slim, no payload.
              // 2026-05-23c+: TWO-LAYER defense.
              //   Layer 1: hardcoded NEVER_SEND list of setting keys. This
              //   doesn't trust the registry — even if dump() returns
              //   adminPushable:true for a sensitive key (e.g., because
              //   the kernel hasn't been updated and !! coerces "encrypted"
              //   to true), we still skip these keys by NAME. Belt for
              //   the registry-flag suspenders.
              //   Layer 2: adminPushable === true strict include.
              // Both must agree before a value is included.
              var NEVER_SEND_KEYS = {
                admin_password: 1, github_pat: 1, github_repo: 1,
                github_branch: 1, manifest_url: 1, lib_cipher: 1,
                api_key: 1, user_name: 1, user_email: 1,
              };
              if (window.eli && window.eli.settings && typeof window.eli.settings.dump === "function") {
                try {
                  var dump = window.eli.settings.dump();
                  var slim = {};
                  Object.keys(dump || {}).forEach(function (k) {
                    if (NEVER_SEND_KEYS[k]) return;          // Layer 1
                    var r = dump[k];
                    if (!r) return;
                    if (r.adminPushable !== true) return;    // Layer 2
                    slim[k] = r.value;
                  });
                  fleetMeta.settings = slim;
                } catch (_e) {}
              }
              // Installed tools list — id, version, disabled flag. Minimal
              // shape; full bundle not uploaded (already on CDN).
              // 2026-05-23 fix: use the SYNC in-memory `_loaded` registry,
              // not eli.tools.list() (which returns a Promise from
              // eli.storage.getAll). The Promise would break the
              // synchronous digest build below.
              try {
                if (window.eli && window.eli.tools && window.eli.tools._loaded) {
                  var loaded = window.eli.tools._loaded;
                  fleetMeta.tools = Object.keys(loaded).map(function (id) {
                    var b = loaded[id] || {};
                    return {
                      id: id,
                      releasedAt: b.releasedAt || null,
                      disabled: !!b.disabled,
                    };
                  }).filter(function (t) { return t.id; });
                }
              } catch (_e) {}
              // 2026-05-23c: pinned dashboard apps via kernel getter.
              // Reading eli_dashboard_apps from LS directly misses the
              // "default pinned" case (key only exists when user
              // customized). eli.dashboard.getPinState() returns the
              // RESOLVED set including defaults, plus pinnedOrder which
              // is null for un-customized users. admin_fleet shows both.
              try {
                if (window.eli && window.eli.dashboard && typeof window.eli.dashboard.getPinState === "function") {
                  var state = window.eli.dashboard.getPinState();
                  if (state && state.pinnedSet) {
                    fleetMeta.dashboardApps = Object.keys(state.pinnedSet);
                    fleetMeta.dashboardCustomized = !!state.pinnedOrder;
                  }
                }
              } catch (_e) {}
              // 2026-05-23c: defense in depth — scrub anything that LOOKS
              // like a known credential pattern before pushing to GitHub.
              // GitHub Push Protection blocks pushes that contain values
              // matching its scanner regexes (Google API key, GitHub PAT,
              // OpenAI sk-..., Slack xox..., JWT). If a value here matches,
              // either a setting was misconfigured or the user manually
              // typed a credential into a settings field. Redact + log so
              // the push still goes through and we can investigate.
              _scrubSecretsInPlace(fleetMeta);
              mergedDigest.fleet = fleetMeta;
            } catch (_fleetErr) { /* tolerate — digest still pushes */ }
            return _githubPut(pat, userKey, mergedDigest, sha).then(function () {
              try { eli.compat.lsSet(LAST_PUSH_KEY, String(Date.now())); } catch (e) {}
              eli.log.event("telemetry", "pushed", { days: mergedDigest.days.length, userKey: userKey, rowCount: rowsAfterSelfTest.length, remoteDays: (remoteDigest && remoteDigest.days ? remoteDigest.days.length : 0) });
              return {
                ok: true,
                days: mergedDigest.days.length,
                localDays: digest.days.length,
                remoteDays: (remoteDigest && remoteDigest.days ? remoteDigest.days.length : 0),
                rowCount: (rowsAfterSelfTest || []).length,
                userKey: userKey,
                consent: consentState,
                didSelfTest: didSelfTest,
                selfTestOk: selfTestOk,
                isWeekendToday: isWeekendToday,
                otherUserKeys: otherUserKeys,
                bootState: window._eliTelemetryBoot || null,
                reason: mergedDigest.days.length === 0
                  ? (isWeekendToday ? "no_data_weekend" : "no_data_weekday")
                  : null,
              };
            });
          });
        });
      });
    }).catch(function (err) {
      // 2026-05-18 v25: surface the actual error message so callers
      // (Settings UI) can show what failed instead of a bare
      // "push_failed". Most common downstream cause is GitHub auth
      // (PAT expired/missing) or network — both produce informative
      // messages we should show the user.
      var em = (err && err.message) || String(err);
      eli.log.event("telemetry", "push_failed", { msg: em });
      return { ok: false, skipped: true, reason: "push_failed", error: em };
    });
  }

  // ─── Public dispatch surface ───────────────────────────────────────
  function _telemetryPush() {
    return _push({ force: true });
  }
  function _telemetryStatus() {
    var userKey = _currentUserKey();
    var consent = _readConsent();
    var lastPushStr = eli.compat.lsGet(LAST_PUSH_KEY);
    var lastPush = lastPushStr ? Number(lastPushStr) : 0;
    if (!userKey) {
      return Promise.resolve({
        userKey: null, consent: consent, lastPushAt: lastPush, dayCount: 0,
      });
    }
    return _allUserRows(userKey).then(function (rows) {
      return {
        userKey: userKey,
        consent: consent,
        lastPushAt: lastPush,
        dayCount: (rows || []).length,
      };
    });
  }

  eli.register({
    telemetry: {
      push: _telemetryPush,
      status: _telemetryStatus,
    },
  });

  // ─── Consent migration v2 (2026-05-17) ───────────────────────────
  // One-time: clear any "opted_out" value persisted before the default
  // flipped to opt-in. Most of those opt-outs came from the (now-
  // removed) first-run dialog, which most users dismissed reflexively.
  // After migration, the Settings → Global → Usage Telemetry toggle is
  // the authoritative opt-out path; a fresh "opted_out" set AFTER this
  // marker exists is honored permanently.
  function _migrateConsentV2() {
    try {
      if (eli.compat.lsGet("_telemetry_migration_v2")) return;
      var cur = String(eli.compat.lsGet(CONSENT_KEY) || "").trim();
      if (cur === "opted_out") {
        eli.compat.lsRemove(CONSENT_KEY);
        eli.log.event("telemetry", "consent_migrated_to_default_on", {});
      }
      eli.compat.lsSet("_telemetry_migration_v2", "1");
    } catch (e) { /* tolerate */ }
  }

  // ─── Boot sequence (default opt-in, no dialog) ───────────────────
  // 2026-05-17 v24: boot-state observability. Each step writes to
  // window._eliTelemetryBoot so the push diagnostic can surface
  // exactly where boot bailed. Was opaque before — silent fail to
  // subscribe looked identical to "no events ever fired."
  window._eliTelemetryBoot = { step: "init", subscribed: false, error: null };
  function _bootStart() {
    try {
      window._eliTelemetryBoot.step = "consent_migration";
      _migrateConsentV2();
      window._eliTelemetryBoot.step = "consent_check";
      if (_readConsent() === "opted_out") {
        eli.log.event("telemetry", "skipped_opted_out", {});
        window._eliTelemetryBoot.step = "skipped_opted_out";
        return;
      }
      window._eliTelemetryBoot.step = "subscribing_stats";
      eli.bus.on("stats:recorded", _onStatsRecorded);
      window._eliTelemetryBoot.step = "subscribing_tokens";
      eli.bus.on("ai:tokens_used", _onTokensUsed);
      window._eliTelemetryBoot.subscribed = true;
      window._eliTelemetryBoot.step = "subscribed";
      eli.log.event("telemetry", "subscribed", {});
      // 2026-05-18 v41: fire session-start unconditionally so sessions
      // is bumped on every boot, independent of whether the user
      // launches any recognized tool that boot.
      _recordSessionStart().catch(function (e) {
        eli.log.event("telemetry", "session_start_failed", { msg: e && e.message });
      });
      // Defer the push so the dashboard finishes painting first.
      setTimeout(function () {
        _push({ force: false }).then(function (r) {
          if (r && r.ok) eli.log.event("telemetry", "boot_push_ok", { days: r.days });
        });
      }, 5000);
    } catch (e) {
      window._eliTelemetryBoot.error = (e && e.message) || String(e);
      eli.log.event("telemetry", "boot_failed", { step: window._eliTelemetryBoot.step, msg: window._eliTelemetryBoot.error });
    }
  }

  _bootStart();
  eli.log.event("tool", "eli_telemetry_initialized", { bootStep: window._eliTelemetryBoot.step, subscribed: window._eliTelemetryBoot.subscribed });
}
